export type RequestOptions = { signal?: AbortSignal; baseUrl?: string };
async function request<T>(path: string, method: string, body: unknown, options: RequestOptions): Promise<T> {
  const response = await fetch((options.baseUrl || '') + path, { method, signal: options.signal, headers: body === undefined ? undefined : { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || response.statusText);
  return value;
}

